import { useId } from "react";
import { ArrowRight } from "lucide-react";

// KMP-C14 (specs/KMP-C14-frozen-week-block.md). Stands where Regenerate stands on next week. The copy is constant:
// it has no prop, so it cannot vary with the day or with whether next week was viewed.

export const FROZEN_WEEK_COPY = "This week is planned and shopped for. Changes start from Monday.";
export const FROZEN_WEEK_ACTION = "Plan next week";

export function FrozenWeekBlock({ href }: { /** Where "Plan next week" goes (next week, generated on arrival). */ href: string }) {
  const id = useId();
  return (
    <div className="flex flex-col items-start gap-stack-sm rounded-control border-bw-default border-border bg-surface-raised p-inset-md font-body text-ui-reading leading-normal">
      <p id={id} className="font-regular text-text">
        {FROZEN_WEEK_COPY}
      </p>
      <a
        href={href}
        aria-describedby={id}
        className="inline-flex min-h-control items-center gap-gap-sm rounded-control px-inset-md font-semibold text-primary-text underline hover:text-text active:text-text focus-visible:outline focus-visible:outline-ring focus-visible:outline-offset-ring focus-visible:outline-focus-ring"
      >
        {FROZEN_WEEK_ACTION}
        <ArrowRight aria-hidden="true" className="size-icon-sm shrink-0" />
      </a>
    </div>
  );
}
